    public struct ValidationEvidenceBody: AWSDecodableShape {
        /// Identifiers of attack flows upgraded to Confirmed provenance.
        public let attackFlowsConfirmed: [String]?
        /// Proof the agent produced by executing code against the repository under
        /// test, with the output that execution produced.
        public let executedProof: ValidationExecutedProof?
        /// Exploitability verdict. Explicit UNCERTAIN replaces the producer's
        /// tri-state `exploitable: true | false | null`, so an absent verdict is
        /// never confused with a negative one.
        public let exploitable: ExploitabilityVerdict
        /// Concrete payload and its observed effect, when validation produced one by
        /// sending an HTTP request.
        /// Only an HTTP proof projects here. A validation agent that proves
        /// exploitability by RUNNING code against the repository projects
        /// `executedProof`, and one that proves it by reading the source projects
        /// `sourceAnalysis`. All three are mutually exclusive: at most one is present.
        public let exploitArtifact: ValidationExploitArtifact?
        /// One verdict per attack flow assessed in the bundle.
        public let flowVerdicts: [FlowVerdict]?
        /// Per-finding breakdown for a multi-finding bundle. Absent for a
        /// single-finding bundle.
        public let perFindingResults: [PerFindingResult]?
        /// Proof the agent produced by reading the repository's source, with nothing
        /// built or run.
        public let sourceAnalysis: ValidationSourceAnalysis?
        /// How the validation run ended. Absent when the producer reported a status
        /// with no mapping yet: the rest of the body still projects, so one
        /// unmapped enum never costs a customer the whole artifact.
        public let terminalStatus: ValidationTerminalStatus?

        @inlinable
        public init(attackFlowsConfirmed: [String]? = nil, executedProof: ValidationExecutedProof? = nil, exploitable: ExploitabilityVerdict, exploitArtifact: ValidationExploitArtifact? = nil, flowVerdicts: [FlowVerdict]? = nil, perFindingResults: [PerFindingResult]? = nil, sourceAnalysis: ValidationSourceAnalysis? = nil, terminalStatus: ValidationTerminalStatus? = nil) {
            self.attackFlowsConfirmed = attackFlowsConfirmed
            self.executedProof = executedProof
            self.exploitable = exploitable
            self.exploitArtifact = exploitArtifact
            self.flowVerdicts = flowVerdicts
            self.perFindingResults = perFindingResults
            self.sourceAnalysis = sourceAnalysis
            self.terminalStatus = terminalStatus
        }

        private enum CodingKeys: String, CodingKey {
            case attackFlowsConfirmed = "attackFlowsConfirmed"
            case executedProof = "executedProof"
            case exploitable = "exploitable"
            case exploitArtifact = "exploitArtifact"
            case flowVerdicts = "flowVerdicts"
            case perFindingResults = "perFindingResults"
            case sourceAnalysis = "sourceAnalysis"
            case terminalStatus = "terminalStatus"
        }
    }

